(()=>{let vz={},hosts={},briefs={},receptors={};const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pair=x=>`<p>${E(x?.[0])}</p><p class="en">${E(x?.[1])}</p>`;const link=(u,t)=>`<a href="${E(u)}" target="_blank" rel="noopener">${E(t)} ↗</a>`;
function genome(id,t){const r=t?(vz.taxonLinks?.[t.genus]||vz.taxonLinks?.[t.family]):vz.profiles?.[id];if(!r)return `<div class="genome-links">${link('https://viralzone.expasy.org/search?query='+encodeURIComponent(t?.name||id),'在 ViralZone 检索 / Search ViralZone')}<small>尚未核对专属条目 / Specific mapping not reviewed</small></div>`;return `<div class="genome-links"><b>ViralZone · ${E(r.title)}</b><div>${link(r.genomeUrl||r.url,'基因组图 / Genome')}${link(r.structureUrl||r.url,'粒子结构 / Virion')}</div>${pair(r.scope||[r.level==='genus'?'属级结构与基因组概览':'科级结构与基因组概览','Family/genus overview; not a strain-specific genome map.'])}${(r.relatedLinks||[]).map(x=>link(x.url,x.title)).join('')}</div>`}
async function status(id){const n=document.querySelector('[data-daily-status="'+id+'"]');if(!n)return;try{const r=await fetch('/api/daily-status',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();const row=d.updates?.find(x=>x.id===id);n.textContent=row?'云端最近检查 / Last cloud check: '+row.checked+' · Papers: '+row.results.papers.status+' · News: '+row.results.news.status:'尚无云端运行记录 / No cloud run recorded yet'}catch{n.textContent='云端状态暂不可用 / Cloud status unavailable'}}

const roles={receptor:['受体','Receptor'],coreceptor:['共受体','Co-receptor'],attachment:['附着受体／因子','Attachment receptor/factor'],cofactor:['辅助因子','Cofactor'],disputed:['未确立／存在反对证据','Not established / counterevidence']};
function receptorSummary(id){return receptors.profiles?.[id]?.summary||['本页面尚未完成该条目的受体文献核验；这不等于该病毒没有已知受体。','Receptor literature has not yet been reviewed for this entry. This does not mean that no receptor is known.']}
function coverage(id){const r=receptors.profiles?.[id];const n=r?.sources?.length||0;return `<aside class="evidence-coverage"><h4>文献覆盖与审核 / Coverage & review</h4><p>受体专用检索截止：尚未建立系统检索记录。基础说明核验：${E(r?.checked||'尚未完成')}。</p><p class="en">Receptor-specific systematic search cutoff: not recorded. Foundational review: ${E(r?.checked||'pending')}.</p><p>已关联并核读摘要：<strong>${n}</strong> 篇 · 全文审核：未登记 · 待审与冲突数量：尚未统计</p><p class="en">Linked references with abstracts reviewed: ${n}. Full-text review, pending items and conflicts: not recorded.</p><details><summary>审核流程与发布规则 / Review workflow</summary><ol><li>论文与新闻追踪器自动发现的新记录作为阅读线索；不自动成为受体证据。</li><li>按 DOI / PMID 核对身份与版本，检查更正及撤稿状态，记录可获得的摘要或全文。</li><li>逐项人工审核结论、来源位置与适用范围；分子角色与证据状态分别标注。</li><li>出现支持或反对的新研究时重新审核；通过审核后更新说明及核验日期。</li></ol><p class="en">Discovery → identity/version checks → human evidence review → approved publication. General research tracking does not establish receptor function.</p><p>这里的数量只表示本页整理范围，不能用于计算完整度。自动研究追踪与受体专用审核是两项不同进度。</p></details></aside>`}
function receptor(id){const r=receptors.profiles?.[id];const sources=(r?.sources||[]).map(k=>receptors.references[k]).filter(Boolean);return `<section class="receptor-evidence"><h3>受体与证据 / Receptors & evidence</h3><span class="receptor-status">${r?'已核验基础说明 / Foundational overview reviewed':'本页未完成核验 / Not reviewed for this page'}</span>${pair(receptorSummary(id))}${coverage(id)}${r?`<div class="receptor-cards">${r.entries.map(x=>`<article class="receptor-card"><span class="pill">${E((roles[x.role]||[])[0])} / ${E((roles[x.role]||[])[1])}</span><h4>${E(x.name)}</h4><p class="evidence-state">证据状态 / Evidence: ${x.role==='disputed'?'存在反对证据 / Counterevidence':'所引基础研究支持；范围见下方 / Supported in cited foundational study; limits below'}</p>${pair(x.explanation)}<div class="receptor-limit"><b>证据边界 / Limits</b>${pair(x.limit)}</div><div class="source-links">${x.refs.map(k=>{const ref=receptors.references[k];return link(ref.url,ref.authors+' · '+ref.year)}).join('')}</div></article>`).join('')}</div><p class="en">核验 / Reviewed ${E(r.checked)} · 基础原始研究摘要；非完整清单、非系统综述 / Foundational primary-study abstracts; not an exhaustive list or systematic review.</p>`:'<p>尚无完成核验的受体专用文献。下方公共卫生来源不作为具体受体作用的证明。<span class="en">No receptor-specific reference has been vetted here. Public-health references below do not establish receptor function.</span></p>'}<details class="receptor-legend"><summary>如何读这些标签 / Reading the labels</summary><p>受体、共受体、附着因子与其他辅助因子的角色不同。“结合”“参与感染”和“证明完整感染过程”不是同一个结论。证据不足／有争议属于研究结论的状态；未核验属于本页面的整理状态，二者不可混用。</p><p class="en">Receptors, co-receptors, attachment factors and other cofactors have distinct roles. Binding or involvement does not establish the entire infection process. Limited/disputed evidence describes the research; unreviewed describes this page.</p></details>${sources.length?`<details><summary>原始文献 / Primary references (${sources.length})</summary><ol>${sources.map(x=>`<li>${link(x.url,x.title)}<p>${E(x.authors)} · ${E(x.year)} · DOI: ${E(x.doi)}</p></li>`).join('')}</ol></details>`:''}</section>`}

function host(id){const h=hosts.profiles?.[id];return h?`<div class="host-context"><h3>宿主与证据背景 / Hosts & evidence</h3>${pair(h.host)}${pair(h.context)}<details><summary>证据边界 / Evidence scope</summary>${pair(h.evidence)}</details><div class="source-links">${h.sources.map(x=>link(x.url,x.title)).join('')}</div></div>`:''}
function brief(x){const b=x.briefData||briefs.papers?.[x.pmid];const reviewed=b&&b.basis!=='metadata';return `<div class="paper-brief" data-brief="${E(x.pmid)}"><span class="brief-basis">${reviewed?(b.basis==='full-text'?'全文解读 / Full-text based':'摘要解读 / Abstract based'):'待核读 · 仅题录 / Metadata only'}</span><h5>In brief · 简述</h5>${pair(b?.brief||['已检索到这篇论文，尚未核读摘要；不能据标题判断研究结果。','This record was retrieved; its abstract has not been reviewed. The title alone does not establish findings.'])}<h5>Highlights · 要点</h5><ul>${(b?.highlights||[{label:'Evidence',text:['研究设计、主要结果与局限尚待核读。','Study design, findings and limitations await review.']}]).map(h=>`<li><b>${E(h.label)}</b>${pair(h.text)}</li>`).join('')}</ul>${b?.sourceUrl?link(b.sourceUrl,'解读来源 / Source'):''}<button class="secondary" data-brief-load="${E(x.pmid)}">检查最新解读 / Check updated brief</button></div>`}
document.addEventListener('click',async e=>{const share=e.target.closest('[data-share-link]');if(share){try{await navigator.clipboard.writeText(location.href);share.textContent='链接已复制 / Link copied'}catch{share.textContent='请复制地址栏链接 / Copy address bar'}return}const b=e.target.closest('[data-brief-load]');if(!b)return;b.disabled=true;const id=b.dataset.briefLoad;try{const r=await fetch('/api/paper-brief?pmid='+encodeURIComponent(id),{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();if(d.brief){briefs.papers[id]=d;b.closest('.paper-brief').outerHTML=brief({pmid:id})}else b.textContent='暂无新解读 / No reviewed update'}catch{b.textContent='连接失败，稍后重试 / Retry later'}finally{b.disabled=false}});
window.AtlasExtras={genome,host,brief,status,receptor,receptorSummary,async init(){[vz,hosts,briefs,receptors]=window.ATLAS_EXTRAS||await Promise.all(['viralzone-links','host-context','paper-briefs','receptor-evidence'].map(n=>fetch(n+'.json?v=6').then(r=>r.json())))}};
})();
